300	\begin{definition}[The swap unitaries]\label{def:v-swap-unitary}
301		\lean{MIPStarRE.QPBT.swapUnitary}
302		\leanok
303		\uses{lem:qld-4-7, def:generalized-pauli, def:decoding-map}
304		Define the linear map
305		\[
306			V_{\mathrm{A}} = \sum_{g_X,g_Z} (\hat{S}_{g_X,g_Z})_{\mathrm{A}\mathrm{A}'} \ot \bigl(\tau^X(\mathrm{Dec}(g_Z)) \, \tau^Z(\mathrm{Dec}(g_X))\bigr)_{\mathrm{A}''}\;,
307		\]
308		where $\tau^X(\cdot)$ and $\tau^Z(\cdot)$ are the generalized Pauli observables acting on $(\C^q)^{\ot M}$; note that the argument of $\tau^X$ is $\mathrm{Dec}(g_Z)$ and the argument of $\tau^Z$ is $\mathrm{Dec}(g_X)$. The map $V_{\mathrm{B}}$, acting on registers $\mathrm{B}\mathrm{B}'\mathrm{B}''$, is defined analogously.
